/*
 * h173k Wallet - service worker additions.
 *
 * THIS IS THE ONLY HAND-WRITTEN SERVICE WORKER CODE IN THE PROJECT.
 *
 * The service worker itself is generated by VitePWA/workbox at build time
 * (caching, precaching, update handling — do not reimplement any of it here).
 * This file is pulled into that generated worker through the `importScripts`
 * entry in vite.config.js, so anything below runs inside the real worker in
 * production.
 *
 * There used to be a second, hand-written public/sw.js as well. It was silently
 * overwritten by the generated worker in production, so edits made to it only
 * ever took effect in `vite dev` — a notification fix once lived there and did
 * nothing for real users. It has been deleted; put service worker changes here
 * and nowhere else.
 */
self.addEventListener('notificationclick', (event) => {
  event.notification.close()
  const data = event.notification.data || {}
  const targetUrl = data.url || '/'
  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      for (const client of clientList) {
        if ('focus' in client) {
          client.focus()
          // Tell the running app which chat to open, instead of navigating and
          // throwing away its state. `group` is set for group notifications,
          // `from` for individual ones.
          if (data.from || data.group) {
            try {
              client.postMessage({ type: 'h173k-open-chat', from: data.from, group: data.group })
            } catch (e) {}
          }
          return
        }
      }
      if (self.clients.openWindow) return self.clients.openWindow(targetUrl)
    })
  )
})

/*
 * Push notifications.
 *
 * Nothing in the app subscribes to push yet (no pushManager.subscribe call), so
 * this never fires today. It is kept so that the day a server starts sending
 * pushes, clicks land in the handler above and open the right chat.
 */
self.addEventListener('push', (event) => {
  let data = {}
  try { data = event.data ? event.data.json() : {} } catch (e) { data = {} }

  event.waitUntil(
    self.registration.showNotification(data.title || 'h173k Wallet', {
      body: data.body || '',
      icon: '/icons/icon-192x192.png',
      badge: '/icons/icon-192x192.png',
      vibrate: [100, 50, 100],
      // An object, matching what the click handler above expects.
      data: { url: data.url || '/', from: data.from, group: data.group },
    })
  )
})
